mapper.select:


    menu.deleted_flag = 'N'
     and menu.remark = #{remark}
     and menu.menu_name like concat('%', #{menuName}, '%')
     and menu.menu_code = #{menuCode}
     and menu.order_num = #{orderNum}
     and menu.path = #{path}
     and menu.component = #{component}
     and menu.params = #{params}
     and menu.is_frame = #{isFrame}
     and menu.is_cache = #{isCache}
     and menu.menu_type = #{menuType}
     and menu.visible = #{visible}
     and menu.status = #{status}
     and menu.permission = #{permission}
     and menu.parent_id = #{parentId}
     and menu.icon = #{icon}
     and menu.organization_id = #{organizationId}

        and

            menu.menu_type =  #{item}



        and

            (
            menu.menu_name like concat('%', #{item}, '%')
            or menu.menu_code like concat('%', #{item}, '%')
            or menu.remark like concat('%', #{item}, '%')
            )



order by menu.order_num desc
